def construct(budget_seconds, start):
    """Code Zero: keep the start if there is one, otherwise 32 small equal circles on a grid."""
    if start is not None:
        return np.asarray(start, dtype=float)
    k = int(np.ceil(np.sqrt(32)))
    pts = [((i + 0.5) / k, (j + 0.5) / k) for j in range(k) for i in range(k)][:32]
    return np.array([[x, y, 0.02] for x, y in pts])

import numpy as np
import time
from scipy.optimize import minimize, linprog


def construct(budget_seconds, start):
    t0 = time.process_time()
    n = 32
    limit = budget_seconds * 0.80
    rng = np.random.default_rng(2024)

    def unpack(v):
        v = np.asarray(v, dtype=float).reshape(-1)
        return v[:2 * n].reshape(n, 2).copy(), v[2 * n:3 * n].copy()

    def pack(xy, r):
        return np.concatenate([xy.reshape(-1), r])

    def pair_dist(xy):
        d = np.linalg.norm(xy[:, None, :] - xy[None, :, :], axis=2)
        np.fill_diagonal(d, np.inf)
        return d

    def repair(xy, r):
        xy = xy.copy(); r = r.copy()
        for _ in range(300):
            changed = False
            wall = np.minimum(np.minimum(xy[:, 0], 1 - xy[:, 0]),
                              np.minimum(xy[:, 1], 1 - xy[:, 1]))
            over_wall = r - (wall - 1e-12)
            if np.any(over_wall > 0):
                r = np.minimum(r, np.maximum(wall - 1e-12, 1e-9))
                changed = True
            d = pair_dist(xy)
            over = (r[:, None] + r[None, :]) - d
            np.fill_diagonal(over, -np.inf)
            if np.any(over > 0):
                for i in range(n):
                    for j in range(i + 1, n):
                        if over[i, j] > 0:
                            s = over[i, j] * 0.5 + 1e-12
                            r[i] = max(r[i] - s, 1e-9)
                            r[j] = max(r[j] - s, 1e-9)
                            changed = True
            if not changed:
                break
        xy[:, 0] = np.clip(xy[:, 0], r, 1 - r)
        xy[:, 1] = np.clip(xy[:, 1], r, 1 - r)
        return xy, r

    def lp_radii(xy):
        x = xy[:, 0]; y = xy[:, 1]
        wall = np.minimum(np.minimum(x, 1 - x), np.minimum(y, 1 - y))
        wall = np.maximum(wall, 0.0)
        d = pair_dist(xy)
        A = []; b = []
        for i in range(n):
            row = np.zeros(n); row[i] = 1.0
            A.append(row); b.append(wall[i])
        for i in range(n):
            for j in range(i + 1, n):
                row = np.zeros(n); row[i] = 1.0; row[j] = 1.0
                A.append(row); b.append(d[i, j])
        A = np.array(A); b = np.array(b)
        try:
            res = linprog(-np.ones(n), A_ub=A, b_ub=b,
                          bounds=[(0, None)] * n, method='highs')
            if res.success:
                return np.maximum(res.x, 1e-9)
        except Exception:
            pass
        return None

    def slsqp_opt(xy0, r0, maxiter=200):
        v0 = pack(xy0, r0)

        def obj(v):
            return -np.sum(v[2 * n:3 * n])

        def cons(v):
            x = v[0:2 * n:2]; y = v[1:2 * n:2]; r = v[2 * n:3 * n]
            c = [x - r, 1 - x - r, y - r, 1 - y - r]
            d2 = ((x[:, None] - x[None, :]) ** 2 +
                  (y[:, None] - y[None, :]) ** 2)
            np.fill_diagonal(d2, 1.0)
            rs = r[:, None] + r[None, :]
            iu = np.triu_indices(n, 1)
            c.append(d2[iu] - rs[iu] ** 2)
            return np.concatenate(c)

        try:
            res = minimize(obj, v0, method='SLSQP',
                           constraints=[{'type': 'ineq', 'fun': cons}],
                           options={'maxiter': maxiter, 'ftol': 1e-14})
            xy, r = unpack(res.x)
            xy, r = repair(xy, r)
            return xy, r, r.sum()
        except Exception:
            return xy0, r0, r0.sum()

    def lp_polish(xy, r, maxiter=100):
        rlp = lp_radii(xy)
        if rlp is None:
            return xy, r, r.sum()
        xy2, r2 = repair(xy, rlp)
        return slsqp_opt(xy2, r2, maxiter=maxiter)

    # ---- LP value and gradient wrt centers ----
    def value_and_grad(xy_flat):
        xy = xy_flat.reshape(n, 2)
        x = xy[:, 0]; y = xy[:, 1]
        wall = np.minimum(np.minimum(x, 1 - x), np.minimum(y, 1 - y))
        wall = np.maximum(wall, 0.0)
        d = pair_dist(xy)
        A = []; b = []
        wall_rows = []
        for i in range(n):
            row = np.zeros(n); row[i] = 1.0
            A.append(row); b.append(wall[i]); wall_rows.append(i)
        pair_rows = []
        for i in range(n):
            for j in range(i + 1, n):
                row = np.zeros(n); row[i] = 1.0; row[j] = 1.0
                A.append(row); b.append(d[i, j]); pair_rows.append((i, j))
        A = np.array(A); b = np.array(b)
        try:
            res = linprog(-np.ones(n), A_ub=A, b_ub=b,
                          bounds=[(0, None)] * n, method='highs')
            if not res.success:
                return 1e6, np.zeros(2 * n)
        except Exception:
            return 1e6, np.zeros(2 * n)
        r = np.maximum(res.x, 1e-12)
        val = -np.sum(r)
        # duals: res.ineqlin.marginals (<=0 for upper-bound constraints)
        lam = np.zeros(len(b))
        try:
            lam = np.asarray(res.ineqlin.marginals, dtype=float)
        except Exception:
            lam = np.zeros(len(b))
        grad = np.zeros((n, 2))
        # wall constraints: r_i <= min(x,1-x,y,1-y)
        for k, i in enumerate(wall_rows):
            li = lam[k]
            if li == 0:
                continue
            # value decreases as wall increases; dval/dwall = -li (li<=0 -> positive)
            # wall = min of four; subgradient
            cands = [(x[i], (1.0, 0.0)),
                     (1 - x[i], (-1.0, 0.0)),
                     (y[i], (0.0, 1.0)),
                     (1 - y[i], (0.0, -1.0))]
            m = min(c[0] for c in cands)
            for cval, cdir in cands:
                if cval <= m + 1e-12:
                    grad[i] += (-li) * cdir
        # pair constraints: r_i + r_j <= d_ij
        for k, (i, j) in enumerate(pair_rows):
            li = lam[len(wall_rows) + k]
            if li == 0:
                continue
            dij = d[i, j]
            if dij < 1e-15:
                continue
            u = (xy[i] - xy[j]) / dij
            # dval/dd = -li (li<=0 -> positive); dd/dxy_i = u
            g = (-li) * u
            grad[i] += g
            grad[j] -= g
        return val, grad.reshape(-1)

    # ---- initial ----
    if start is not None:
        s = np.asarray(start, dtype=float)
        xy = s[:, :2].copy(); r = s[:, 2].copy()
        xy, r = repair(xy, r)
    else:
        k = 6
        pts = []
        for j in range(k):
            for i in range(k):
                x = (i + 0.5 + (0.5 if j % 2 else 0)) / k
                y = (j + 0.5) / k
                pts.append((x, y))
        pts = pts[:n]
        xy = np.array(pts)
        r = np.full(n, 0.03)
        xy, r = repair(xy, r)

    best_xy, best_r, best_score = slsqp_opt(xy, r, maxiter=300)
    xy_p, r_p, sc_p = lp_polish(best_xy, best_r, maxiter=100)
    if sc_p > best_score:
        best_score, best_xy, best_r = sc_p, xy_p, r_p

    # ---- L-BFGS-B on centers using LP value+gradient ----
    def run_lbfgs(xy0):
        v0 = xy0.reshape(-1).copy()
        try:
            res = minimize(value_and_grad, v0, method='L-BFGS-B',
                           jac=True,
                           bounds=[(0.0, 1.0)] * (2 * n),
                           options={'maxiter': 200, 'ftol': 1e-15,
                                    'gtol': 1e-12})
            xy2 = res.x.reshape(n, 2)
            rlp = lp_radii(xy2)
            if rlp is None:
                return xy0, None, -1e9
            xy2, r2 = repair(xy2, rlp)
            return xy2, r2, r2.sum()
        except Exception:
            return xy0, None, -1e9

    xy_l, r_l, sc_l = run_lbfgs(best_xy)
    if r_l is not None and sc_l > best_score:
        best_score, best_xy, best_r = sc_l, xy_l, r_l
    # polish with SLSQP
    if time.process_time() - t0 < limit:
        xy_s, r_s, sc_s = slsqp_opt(best_xy, best_r, maxiter=150)
        if sc_s > best_score:
            best_score, best_xy, best_r = sc_s, xy_s, r_s

    # ---- restarts with jitter ----
    tries = 0
    while time.process_time() - t0 < limit and tries < 40:
        tries += 1
        scale = 0.01 if tries < 10 else 0.03
        xy2 = best_xy + rng.normal(scale=scale, size=best_xy.shape)
        xy2[:, 0] = np.clip(xy2[:, 0], 0.001, 0.999)
        xy2[:, 1] = np.clip(xy2[:, 1], 0.001, 0.999)
        r2 = best_r * (0.95 + 0.1 * rng.random(n))
        xy2, r2 = repair(xy2, r2)
        xy2, r2, sc = slsqp_opt(xy2, r2, maxiter=120)
        if time.process_time() - t0 < limit:
            xy3, r3, sc3 = run_lbfgs(xy2)
            if r3 is not None and sc3 > sc:
                xy2, r2, sc = xy3, r3, sc3
        if time.process_time() - t0 < limit:
            xy4, r4, sc4 = lp_polish(xy2, r2, maxiter=80)
            if sc4 > sc:
                xy2, r2, sc = xy4, r4, sc4
        if sc > best_score:
            best_score, best_xy, best_r = sc, xy2, r2

    # ---- final strict safety shrink ----
    xy = best_xy.copy(); r = best_r.copy()
    r = r - 1e-10
    r = np.maximum(r, 1e-9)
    xy[:, 0] = np.clip(xy[:, 0], r, 1 - r)
    xy[:, 1] = np.clip(xy[:, 1], r, 1 - r)
    for _ in range(50):
        d = pair_dist(xy)
        area = (r[:, None] + r[None, :]) - d
        np.fill_diagonal(area, -np.inf)
        mx = area.max()
        if mx <= 0:
