            np.fill_diagonal(over, -np.inf)
            if np.any(over > 0):
                for i in range(n):
                    for j in range(i + 1, n):
                        if over[i, j] > 0:
                            s = over[i, j] * 0.5 + 1e-12
                            r[i] = max(r[i] - s, 1e-9)
                            r[j] = max(r[j] - s, 1e-9)
                            changed = True
            if not changed:
                break
        xy[:, 0] = np.clip(xy[:, 0], r, 1 - r)
        xy[:, 1] = np.clip(xy[:, 1], r, 1 - r)
        return xy, r

    def slsqp_opt(xy0, r0, maxiter=200):
        v0 = pack(xy0, r0)

        def obj(v):
            return -np.sum(v[2 * n:3 * n])

        def cons(v):
            x = v[0:2 * n:2]; y = v[1:2 * n:2]; r = v[2 * n:3 * n]
            c = [x - r, 1 - x - r, y - r, 1 - y - r]
            d2 = ((x[:, None] - x[None, :]) ** 2 +
                  (y[:, None] - y[None, :]) ** 2)
            np.fill_diagonal(d2, 1.0)
            rs = r[:, None] + r[None, :]
            iu = np.triu_indices(n, 1)
            c.append(d2[iu] - rs[iu] ** 2)
            return np.concatenate(c)

        try:
            res = minimize(obj, v0, method='SLSQP',
                           constraints=[{'type': 'ineq', 'fun': cons}],
                           options={'maxiter': maxiter, 'ftol': 1e-14})
            xy, r = unpack(res.x)
            xy, r = repair(xy, r)
            return xy, r, r.sum()
        except Exception:
            return xy0, r0, r0.sum()

    # ---- fresh start generators ----
    def grid_start(rows, cols):
        pts = []
        for j in range(rows):
            for i in range(cols):
                if len(pts) >= n:
                    break
                pts.append(((i + 0.5) / cols, (j + 0.5) / rows))
        pts = pts[:n]
        xy = np.array(pts)
        r = np.full(len(xy), 0.03)
        return repair(xy, r)

    def staggered_start(row_counts):
        pts = []
        R = len(row_counts)
        for j, cnt in enumerate(row_counts):
            for i in range(cnt):
                x = (i + 0.5) / cnt
                if j % 2 == 1:
                    x = (i + 1.0) / (cnt + 1)
                y = (j + 0.5) / R
                pts.append((x, y))
        pts = pts[:n]
        xy = np.array(pts)
        r = np.full(len(xy), 0.03)
        return repair(xy, r)

    def hex_start(k):
        pts = []
        for j in range(k):
            for i in range(k):
                x = (i + 0.5 + (0.5 if j % 2 else 0)) / k
                y = (j + 0.5) / k
                pts.append((x, y))
        pts = pts[:n]
        xy = np.array(pts)
        r = np.full(len(xy), 0.03)
        return repair(xy, r)

    def random_start():
        xy = rng.random((n, 2)) * 0.8 + 0.1
        r = np.full(n, 0.03)
        return repair(xy, r)

    # ---- base fallback ----
    if start is not None:
        s = np.asarray(start, dtype=float)
        bxy = s[:, :2].copy(); br = s[:, 2].copy()
        bxy, br = repair(bxy, br)
        best_xy, best_r, best_score = bxy, br, br.sum()
    else:
        best_xy, best_r, best_score = grid_start(6, 6)[0], grid_start(6, 6)[1], 0.0
        best_xy, best_r, best_score = slsqp_opt(best_xy, best_r, maxiter=300)

    # ---- fresh starts ----
    fresh = []
    fresh.append(grid_start(4, 8))
    fresh.append(grid_start(8, 4))
    fresh.append(staggered_start([7, 6, 6, 7, 6]))
    fresh.append(staggered_start([6, 5, 5, 5, 5, 6]))
    fresh.append(hex_start(6))
    fresh.append(random_start())
    fresh.append(random_start())
    fresh.append(random_start())

    for (xy0, r0) in fresh:
        if time.process_time() - t0 > limit:
            break
        xy, r, sc = slsqp_opt(xy0, r0, maxiter=300)
        if sc > best_score:
            best_score, best_xy, best_r = sc, xy, r

    # ---- strict final shrink ----
    xy = best_xy.copy(); r = best_r.copy()
    r = r - 1e-10
    r = np.maximum(r, 1e-9)
    xy[:, 0] = np.clip(xy[:, 0], r, 1 - r)
    xy[:, 1] = np.clip(xy[:, 1], r, 1 - r)
    for _ in range(50):
        d = pair_dist(xy)
        area = (r[:, None] + r[None, :]) - d
        np.fill_diagonal(area, -np.inf)
        mx = area.max()
        if mx <= 0:
            break
        r = r * (1 - 2e-10)
        r = np.maximum(r, 1e-9)

    out = np.empty((n, 3))
    out[:, :2] = xy
    out[:, 2] = r
    return out
